import { useMemo } from 'react';
import { useProfile } from '../context/ProfileContext';
import { buildReferralIdentity, type ReferralIdentity } from '../scripts/referralData';

/**
 * The referral identity for the signed-in user, built from the profile the
 * frontend already holds (`ProfileContext`).
 *
 * The code is a deterministic preview generated by `buildDemoReferralCode()` —
 * it is NOT issued or verified by a server, and every surface that renders it
 * shows it as a preview until the referral backend exists.
 */
export function useReferralIdentity(): ReferralIdentity {
  const profile = useProfile();
  const seed = `${profile.firstName} ${profile.lastName} ${profile.email}`;
  return useMemo(() => buildReferralIdentity(seed), [seed]);
}
